def somme_carres(n):
    total = 0
    for i in range(1, n + 1):
        total += i ** 2
    return total

def etapes_syracuse(n):
    etapes = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        etapes += 1
    return etapes

