def moyennes_par_classe(eleves):
    groupes = {}
    for e in eleves:
        groupes.setdefault(e["classe"], []).append(e["note"])
    resultat = {}
    for classe, notes in groupes.items():
        resultat[classe] = round(sum(notes) / len(notes), 2)
    return resultat
